sys_script_include.script:
var UtilBaseAIAB = Class.create();
UtilBaseAIAB.prototype = {
    initialize: function() {},

    getUserName: function(userId) {
        var sys_user = new GlideRecord("sys_user");
        if (sys_user.get(userId)) {
            return sys_user.getValue("user_name");
        }
        return "NO USER FOUND with userId " + userId;
    },

    /**
     * Convert Markdown to HTML for display
     * @param {string} text - The markdown text to convert
     * @returns {string} HTML formatted text
     */
    markdownToHtml: function(text) {
        if (!text) return '';
        var html = text;
        // Bold: **text** or __text__
        html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');
        // Italic: *text* or _text_
        html = html.replace(/\*([^\*]+)\*/g, '<em>$1</em>');
        html = html.replace(/_([^_]+)_/g, '<em>$1</em>');
        // Links: [text](url)
        html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#1565c0;" target="_blank">$1</a>');
        // Convert newlines to breaks
        html = html.replace(/\n/g, '<br>');
        return html;
    },

    /**
     * Impersonate a user - callable from scoped apps
     * @param {string} userId - sys_id of user to impersonate
     * @returns {string|null} - original user sys_id if successful, null if failed
     */
    impersonate: function(userId) {
        if (!userId) {
            gs.warn("AIABGlobalHelper.impersonate: No userId provided");
            return null;
        }
        var originalUser = gs.getUserID();
        var originalUserName = this.getUserName(originalUser);
        gs.info("AIABGlobalHelper.impersonate: attempting " + userId + " from " + originalUser + "[" + originalUserName + "]");

        try {
            var impersonator = new GlideImpersonate();
            impersonator.impersonate(userId);

            var newUser = gs.getUserID();
            var newUserName = this.getUserName(newUser);
            gs.info("AIABGlobalHelper.impersonate: now running as " + newUser + "[" + newUserName + "]");

            if (newUser === userId) {
                gs.info("AIABGlobalHelper.impersonate: SUCCESS");
                return originalUser;
            } else {
                gs.warn("AIABGlobalHelper.impersonate: FAILED - still " + newUser);
                return null;
            }
        } catch (e) {
            gs.error("AIABGlobalHelper.impersonate: EXCEPTION - " + e);
            return null;
        }
    },

    /**
     * Revert impersonation to original user
     * @param {string} originalUserId - sys_id of original user
     */
    revert: function(originalUserId) {
        if (originalUserId) {
            try {
                var impersonator = new GlideImpersonate();
                impersonator.impersonate(originalUserId);
                gs.info("AIABGlobalHelper.revert: reverted to " + originalUserId);
            } catch (e) {
                gs.warn("AIABGlobalHelper.revert failed: " + e);
            }
        }
    },
    /**
     * Build messages array for table-based inference (summarize-simple type)
     * Looks for a summarize tool for the table and executes it to build prompt
     * @param {GlideRecord} inferenceGR - The u_ai_inference record
     * @param {string} table - Table name
     * @param {string} target - Target record sys_id
     * @param {string} userId - Requesting user sys_id
     * @returns {Array} Messages array for LLM
     */
    buildTableMessages: function(inferenceGR, table, target, userId) {
        var task = new GlideRecord(table);
        if (!task.get(target)) {
            return [{
                role: 'system',
                content: 'Error: Could not find target record'
            }];
        }

        // Look for a summarize tool for this table
        var toolName = 'summarize_' + table;
        var toolGR = new GlideRecord('u_ai_tool');
        toolGR.addQuery('u_name', toolName);
        toolGR.addQuery('u_active', true);
        toolGR.setLimit(1);
        toolGR.query();

        if (toolGR.next()) {
            // Add this tool to the inference's u_tools_included list
            var toolsList = inferenceGR.u_tools_included || '';
            if (toolsList) {
                toolsList += ',';
            }
            toolsList += toolGR.getUniqueValue();
            inferenceGR.u_tools_included = toolsList;

            // Execute the tool to get the prompt
            var evaluator = new GlideScopedEvaluator();
            evaluator.putVariable('args', {
                sys_id: target
            });
            evaluator.putVariable('userId', userId);

            try {
                var result = evaluator.evaluateScript(toolGR, 'u_script');

                if (result && result.found && result.prompt) {
                    // Build messages array from tool output
                    return [{
                        role: 'system',
                        content: 'You are a helpful assistant that summarizes records concisely.'
                    }, {
                        role: 'user',
                        content: result.prompt
                    }];
                } else if (result && result.error) {
                    gs.warn('AIAB: Tool execution error for ' + toolName + ': ' + result.error);
                }
            } catch (e) {
                gs.warn('AIAB: Failed to execute tool ' + toolName + ': ' + e);
            }
        }

        // Fallback: return basic error if no tool found
        return [{
            role: 'system',
            content: 'Error: No summarize tool available for table ' + table
        }];
    },
    /**
     * Convert prompt string to JSON message array
     * Handles both simple prompts and pre-formatted JSON arrays
     * @param {string} prompt - The prompt string
     * @returns {Array} Messages array
     */
    setPromptToJSON: function(prompt) {
        var messages = [{
            role: "system",
            content: "You are a helpful assistant."
        }, {
            role: "user",
            content: prompt
        }];
        try {
            var parsedPrompt = JSON.parse(prompt);
            if (Array.isArray(parsedPrompt)) {
                messages = parsedPrompt;
            }
            return messages;
        } catch (e) {
            return messages;
        }
    },
    /**
     * Get all active tools for an inference
     * Dynamically injects skill list into the skill tool description
     * @param {GlideRecord} inferenceGR - The u_ai_inference record
     * @returns {Array} Array of tool objects for OpenAI API
     */
    getActiveTools: function(inferenceGR) {
        var tools = [];
        var toolIds = [];

        // First, build the dynamic skill list
        var skillList = [];
        var skillGR = new GlideRecord('u_ai_skill');
        skillGR.addQuery('u_active', true);
        skillGR.query();
        while (skillGR.next()) {
            var skillName = skillGR.getValue('u_name');
            var skillDesc = skillGR.getValue('u_description') || 'No description';
            skillList.push('- ' + skillName + ': ' + skillDesc);
        }
        var skillListText = skillList.length > 0 ? 
            skillList.join('\n') : 
            'No skills currently available';

        // First check if u_tools_included is set and use those specific tools
        if (inferenceGR.u_tools_included) {
            var includedIds = inferenceGR.u_tools_included.toString().split(',');
            for (var i = 0; i < includedIds.length; i++) {
                var toolGR = new GlideRecord('u_ai_tool');
                if (toolGR.get(includedIds[i].trim())) {
                    if (toolGR.u_active == true) {
                        try {
                            var toolDescription = toolGR.getValue('u_description');

                            // If this is the skill tool, inject the dynamic list
                            if (toolGR.getValue('u_name') === 'skill') {
                                toolDescription = toolDescription.replace('{{SKILL_LIST}}', skillListText);
                            }

                            tools.push({
                                type: "function",
                                "function": {
                                    name: toolGR.getValue('u_name'),
                                    description: toolDescription,
                                    parameters: JSON.parse(toolGR.getValue('u_parameters'))
                                }
                            });
                            toolIds.push(toolGR.getUniqueValue());
                        } catch (e) {
                            gs.warn('AIAB: Failed to parse tool parameters for ' + toolGR.getValue('u_name') + ': ' + e);
                        }
                    }
                }
            }
        }

        // If no specific tools included, fall back to all active tools
        if (tools.length === 0) {
            var toolGR = new GlideRecord('u_ai_tool');
            toolGR.addQuery('u_active', true);
            toolGR.query();
            while (toolGR.next()) {
                try {
                    var toolDescription = toolGR.getValue('u_description');

                    // If this is the skill tool, inject the dynamic list
                    if (toolGR.getValue('u_name') === 'skill') {
                        toolDescription = toolDescription.replace('{{SKILL_LIST}}', skillListText);
                    }

                    tools.push({
                        type: "function",
                        "function": {
                            name: toolGR.getValue('u_name'),
                            description: toolDescription,
                            parameters: JSON.parse(toolGR.getValue('u_parameters'))
                        }
                    });
                    toolIds.push(toolGR.getUniqueValue());
                } catch (e) {
                    gs.warn('AIAB: Failed to parse tool parameters for ' + toolGR.getValue('u_name') + ': ' + e);
                }
            }

            // Record which tools were implicitly used
            if (toolIds.length > 0) {
                inferenceGR.u_tools_included = toolIds.join(',');
                gs.info('AIAB: Implicitly set ' + toolIds.length + ' tools on inference ' + inferenceGR.getValue('sys_id'));
            }
        }

        // Log the skill list for debugging
        if (skillList.length > 0) {
            gs.info('AIAB: Injected ' + skillList.length + ' skills into skill tool description');
        }

        return tools;
    },
    /**
     * Check and update tool call count for a session
     * Prevents infinite loops by limiting tool calls per session
     * @param {string} sessionId - u_ai_session sys_id
     * @param {number} maxCalls - Maximum allowed calls (default 10)
     * @param {number} increment - Number to increment by (default 1)
     * @returns {Object} { allowed: boolean, current: number, remaining: number }
     */
    checkToolCallLimit: function(sessionId, maxCalls, increment) {
        maxCalls = maxCalls || 10;
        increment = increment || 1;

        var sessionGR = new GlideRecord('u_ai_session');
        if (!sessionGR.get(sessionId)) {
            return {
                allowed: false,
                error: 'Session not found: ' + sessionId
            };
        }

        var currentCount = parseInt(sessionGR.u_tool_call_count || 0);
        var remaining = maxCalls - currentCount;

        if (currentCount >= maxCalls) {
            return {
                allowed: false,
                current: currentCount,
                remaining: 0,
                error: 'Maximum tool call limit (' + maxCalls + ') exceeded'
            };
        }

        // Increment the count
        sessionGR.u_tool_call_count = currentCount + increment;
        sessionGR.update();

        return {
            allowed: true,
            current: currentCount + increment,
            remaining: remaining - increment
        };
    },
    executeTool: function(toolName, toolArgs, userId) {
        if (toolName === 'skill') {
            // Handle skill tool specially
            var skillGR = new GlideRecord('u_ai_skill');
            skillGR.addQuery('u_name', toolArgs.name);
            skillGR.addQuery('u_active', true);
            skillGR.setLimit(1);
            skillGR.query();
            if (skillGR.next()) {
                return {
                    loaded: true,
                    skill_name: '' + skillGR.u_name,
                    content: '' + skillGR.u_content
                };
            }
            return {
                error: 'Skill not found: ' + toolArgs.name
            };
        }

        // Execute regular tool
        var toolGR = new GlideRecord('u_ai_tool');
        toolGR.addQuery('u_name', toolName);
        toolGR.addQuery('u_active', true);
        toolGR.setLimit(1);
        toolGR.query();
        if (!toolGR.next()) {
            return {
                error: 'Tool not found: ' + toolName
            };
        }

        var evaluator = new GlideScopedEvaluator();
        evaluator.putVariable('args', toolArgs);
        evaluator.putVariable('userId', userId);
        return evaluator.evaluateScript(toolGR, 'u_script');
    },
    getOrCreateSession: function(inferenceGR, userId) {
        if (inferenceGR.u_ai_session) {
            return inferenceGR.u_ai_session;
        }
        // Create new session
        var sessionGR = new GlideRecord('u_ai_session');
        sessionGR.initialize();
        sessionGR.u_user = userId;
        sessionGR.u_title = 'AI Session ' + new GlideDateTime().getDisplayValue();
        sessionGR.u_tool_call_count = 0;
        var sessionId = sessionGR.insert();
        inferenceGR.u_ai_session = sessionId;
        return sessionId;
    },

    /**
     * Chunk text into an array of smaller strings
     * @param {string} text - The text to chunk
     * @param {number} chunkSize - Maximum size of each chunk
     * @returns {Array} Array of text chunks
     */
    chunkText: function(text, chunkSize) {
        if (!text) {
            throw "No text given";
        }
        if (!chunkSize) {
            throw "No chunkSize given";
        }
        var chunkedText = [];
        var i = 0;
        var n = text.length;
        while (i < n) {
            chunkedText.push(text.slice(i, i += chunkSize));
        }
        return chunkedText;
    },

    /**
     * Convert HTML to Markdown
     * @param {string} html - The HTML to convert
     * @returns {string} Markdown formatted text
     */
    htmlToMarkdown: function(html) {
        var tree = this._parseHTML(html);
        var markdown = this._processNode(tree).trim().replace(/\n{3,}/g, '\n\n');
        var emptyLinks = markdown.match(/\[\]\(\)/g);
        if (emptyLinks) {
            for (var i = 0; i < emptyLinks.length; i++) {
                markdown = markdown.replace(emptyLinks[i], '');
            }
        }
        return markdown;
    },

    _parseHTML: function(html) {
        var root = {
            type: 'root',
            children: []
        };
        var stack = [root];
        var current = root;
        var pos = 0;
        var voidElements = {
            img: 1,
            br: 1,
            hr: 1,
            meta: 1,
            link: 1,
            input: 1
        };
        var skipTags = {
            style: 1,
            script: 1
        };

        while (pos < html.length) {
            if (html[pos] === '<') {
                var end = html.indexOf('>', pos);
                if (end === -1) break;

                var tagContent = html.substring(pos + 1, end).replace(/\/$/, '');
                var isClosing = tagContent[0] === '/';
                var spaceIndex = tagContent.indexOf(' ');
                var tagName = (isClosing ? tagContent.substring(1) : tagContent)
                    .toLowerCase().split(/\s+/)[0];

                if (!isClosing && skipTags[tagName]) {
                    var closingTag = '</' + tagName + '>';
                    var tagEnd = html.indexOf(closingTag, end);
                    if (tagEnd === -1) {
                        pos = html.length;
                    } else {
                        pos = tagEnd + closingTag.length;
                    }
                    continue;
                }

                if (isClosing) {
                    while (stack.length > 1 && current.tagName !== tagName) {
                        stack.pop();
                        current = stack[stack.length - 1];
                    }
                    if (current.tagName === tagName) {
                        stack.pop();
                        current = stack[stack.length - 1];
                    }
                } else {
                    var node = {
                        type: 'element',
                        tagName: tagName,
                        attributes: this._parseAttributes(tagContent),
                        children: []
                    };

                    current.children.push(node);
                    if (!voidElements[tagName] && !tagContent.endsWith('/')) {
                        stack.push(node);
                        current = node;
                    }
                }
                pos = end + 1;
            } else {
                var textEnd = html.indexOf('<', pos);
                if (textEnd === -1) textEnd = html.length;
                var text = html.substring(pos, textEnd)
                    .replace(/&nbsp;/g, ' ')
                    .replace(/\r?\n/g, '\n')
                    .replace(/[^\S\n]+/g, ' ')
                    .trim();

                if (text) {
                    current.children.push({
                        type: 'text',
                        value: text
                    });
                }
                pos = textEnd;
            }
        }
        return root;
    },

    _parseAttributes: function(attrString) {
        var attrs = {};
        var matches = attrString.match(/(\w+)=["']([^"']*)["']/g) || [];
        for (var i = 0; i < matches.length; i++) {
            var pair = matches[i].split('=');
            attrs[pair[0]] = pair[1].replace(/^["']|["']$/g, '');
        }
        return attrs;
    },

    _processNode: function(node) {
        if (node.type === 'text') {
            return node.value.replace(/\n/g, ' ')
                .replace(/  +/g, ' ');
        }

        var tag = node.tagName;
        var children = node.children || [];

        if (/^h[1-6]$/.test(tag)) {
            var level = parseInt(tag.charAt(1), 10);
            return '\n' + Array(level + 1).join('#') + ' ' + this._processChildren(children) + '\n';
        }

        if (tag === 'p') {
            return '\n' + this._processChildren(children).replace(/\n/g, ' ') + '\n\n';
        }

        if (tag === 'ul') return this._processList(children, false);
        if (tag === 'ol') return this._processList(children, true);
        if (tag === 'li') return this._processChildren(children) + '\n';

        if (tag === 'a') {
            var href = node.attributes.href || '';
            return '[' + this._processChildren(children) + '](' + href + ')';
        }

        if (tag === 'img') {
            var src = node.attributes.src || '';
            var alt = node.attributes.alt || '';
            return '![' + alt + '](' + src + ')';
        }

        if (tag === 'strong' || tag === 'b') return '**' + this._processChildren(children) + '**';
        if (tag === 'em' || tag === 'i') return '*' + this._processChildren(children) + '*';
        if (tag === 'code') return '`' + this._processChildren(children) + '`';
        if (tag === 'pre') return '\n```\n' + this._processChildren(children) + '\n```\n';
        if (tag === 'blockquote') {
            return '> ' + this._processChildren(children).replace(/\n/g, '\n> ');
        }
        if (tag === 'br') return '  \n';
        if (tag === 'div' || tag === 'section') return this._processChildren(children) + '\n';

        return this._processChildren(children);
    },

    _processChildren: function(children) {
        var output = '';
        for (var i = 0; i < children.length; i++) {
            output += this._processNode(children[i]);
        }
        return output;
    },

    _processList: function(items, isOrdered) {
        var output = '';
        var count = 1;

        for (var i = 0; i < items.length; i++) {
            var bullet = isOrdered ? count++ + '. ' : '- ';
            output += bullet + this._processNode(items[i]).trim() + '\n';

            for (var j = 0; j < items[i].children.length; j++) {
                var child = items[i].children[j];
                if (child.tagName === 'ul' || child.tagName === 'ol') {
                    output += this._processList(child.children, child.tagName === 'ol');
                }
            }
        }
        return output;
    },

    type: 'UtilBaseAIAB'
};
